class MainActivity : AppCompatActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)
        // Initialize once
    }

    override fun onResume() {
        super.onResume()
        // Start animations, sensors, etc.
    }

    override fun onPause() {
        super.onPause()
        // Pause animations, release resources
    }
}

// ❌ Lost on rotation
class MyActivity : AppCompatActivity() {
    var counter = 0  // reset to 0 on rotation!
}

// ✅ Survives rotation
class MyViewModel : ViewModel() {
    var counter by mutableStateOf(0)
        private set
    fun increment() { counter++ }
}

class LocationTracker : DefaultLifecycleObserver {
    override fun onResume(owner: LifecycleOwner) {
        startTracking()
    }
    override fun onPause(owner: LifecycleOwner) {
        stopTracking()
    }
}

// In Activity — just add the observer
class MapActivity : AppCompatActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        lifecycle.addObserver(LocationTracker())
    }
}

override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); setContentView(R.layout.main) }
override fun onStart() { super.onStart() /* becoming visible */ }
override fun onResume() { super.onResume(); startCameraPreview() /* fully interactive */ }

override fun onSaveInstanceState(outState: Bundle) {
    super.onSaveInstanceState(outState)
    outState.putInt("selectedTab", selectedTabIndex)
}

override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    selectedTabIndex = savedInstanceState?.getInt("selectedTab") ?: 0
}

class MyViewModel(private val savedStateHandle: SavedStateHandle) : ViewModel() {
    // survives config changes automatically via the ViewModel itself
    var cachedResults: List<Item> = emptyList()

    // survives process death too, since it's backed by SavedStateHandle
    var query: String by savedStateHandle.saveable("query") { mutableStateOf("") }
}

// Risky — may never run if the process is killed directly:
override fun onDestroy() { super.onDestroy(); flushCriticalData() }

// More reliable — called far more consistently before backgrounding:
override fun onStop() { super.onStop(); flushCriticalData() }

override fun onDestroy() {
    super.onDestroy()
    if (isFinishing) {
        cleanupPermanently() // genuinely leaving
    } else if (isChangingConfigurations) {
        // being recreated — no need to tear down resources meant to persist
    }
}

class LocationTracker : DefaultLifecycleObserver {
    override fun onStart(owner: LifecycleOwner) { startTracking() }
    override fun onStop(owner: LifecycleOwner) { stopTracking() }
}

// in the Activity:
lifecycle.addObserver(LocationTracker())

class MyFragment : Fragment() {
    private var _binding: FragmentMainBinding? = null
    private val binding get() = _binding!!

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null // view destroyed here, Fragment instance may persist
    }
}

override fun onNewIntent(intent: Intent) {
    super.onNewIntent(intent)
    setIntent(intent) // update so getIntent() reflects the latest launch
    handleDeepLink(intent)
}

private var _binding: FragmentMainBinding? = null
private val binding get() = _binding!!

override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
    _binding = FragmentMainBinding.inflate(inflater, container, false)
    return binding.root
}

override fun onDestroyView() { super.onDestroyView(); _binding = null }

override fun onMultiWindowModeChanged(isInMultiWindowMode: Boolean, newConfig: Configuration) {
    super.onMultiWindowModeChanged(isInMultiWindowMode, newConfig)
    if (isInMultiWindowMode) adjustLayoutForSplitScreen()
}

override fun onRestart() {
    super.onRestart()
    refreshDataIfStale() // only runs when returning from fully stopped, not from a dialog dismiss
}

private val pickImageLauncher = registerForActivityResult(
    ActivityResultContracts.GetContent()
) { uri: Uri? -> uri?.let { handlePickedImage(it) } }

// later, anywhere after registration:
pickImageLauncher.launch("image/*")

class SearchViewModel(private val savedStateHandle: SavedStateHandle) : ViewModel() {
    var query: String
        get() = savedStateHandle["query"] ?: ""
        set(value) { savedStateHandle["query"] = value } // survives process death, unlike a plain var
}

// Leak risk: singleton holds an Activity reference indefinitely
object AnalyticsHolder { var context: Context? = null } // never assign an Activity here
AnalyticsHolder.context = applicationContext // use applicationContext instead of 'this'

lifecycle.addObserver(LifecycleEventObserver { _, event ->
    when (event) { Lifecycle.Event.ON_START -> {} else -> {} } // reacts to a transition
})

lifecycleScope.launch {
    repeatOnLifecycle(Lifecycle.State.STARTED) { /* maintains this state condition */ }
}

lifecycleScope.launch {
    repeatOnLifecycle(Lifecycle.State.STARTED) {
        viewModel.uiState.collect { state -> render(state) }
    } // collection auto-cancels on stop, auto-restarts on start
}

override fun onTrimMemory(level: Int) {
    super.onTrimMemory(level)
    if (level >= ComponentCallbacks2.TRIM_MEMORY_UI_HIDDEN) {
        imageCache.evictAll() // release memory proactively before a possible kill
    }
}

// Risky — tied to Activity lifecycle and subject to background limits:
lifecycleScope.launch { uploadInBackground() }

// More reliable for guaranteed background completion:
WorkManager.getInstance(context).enqueue(uploadWorkRequest)

override fun onWindowFocusChanged(hasFocus: Boolean) {
    super.onWindowFocusChanged(hasFocus)
    if (!hasFocus) pauseGameInput() // more precise than relying on onPause alone
}

val callback = object : OnBackPressedCallback(true) {
    override fun handleOnBackStarted(backEvent: BackEventCompat) { showPreview() }
    override fun handleOnBackCancelled() { revertPreview() } // gesture cancelled mid-swipe
    override fun handleOnBackPressed() { finish() }
}

@Test
fun survivesRecreation() {
    val scenario = ActivityScenario.launch(MainActivity::class.java)
    scenario.onActivity { it.selectedTabIndex = 2 }
    scenario.recreate() // simulates a configuration change
    scenario.onActivity { assertEquals(2, it.selectedTabIndex) }
}
